import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { log } from "@clack/prompts";
import { stringifyJson } from "./output.js";
import { isInteractive } from "./utils.js";

const AGENTS_MD_START = "<!-- TESTERARMY-SCOUT:START -->";
const AGENTS_MD_END = "<!-- TESTERARMY-SCOUT:END -->";
const SKILL_NAME = "scout";
const BUNDLED_SKILL_PATH = fileURLToPath(new URL("../skills/scout/SKILL.md", import.meta.url));

export type AgentInitOptions = {
  json?: boolean;
  skipSkillInstall?: boolean;
  skipAgentsMd?: boolean;
  cwd?: string;
  skillSource?: string;
};

type AgentInitResult = {
  success: boolean;
  skill: {
    name: string;
    path: string;
    installed: boolean;
    skipped: boolean;
  };
  agentsMd: {
    path: string;
    written: boolean;
    skipped: boolean;
  };
  nextSteps: string[];
};

/** Installs the bundled scout skill and AGENTS.md discovery hints into a repo. */
export async function runAgentInitCommand(options: AgentInitOptions): Promise<void> {
  const cwd = options.cwd ?? process.cwd();
  const install = options.skipSkillInstall
    ? skippedSkillInstall(cwd)
    : installBundledSkill(cwd, options.skillSource ?? BUNDLED_SKILL_PATH);
  const agentsMd = options.skipAgentsMd ? skippedAgentsMd(cwd) : writeLocalAgentsMd(cwd);
  const result: AgentInitResult = {
    success: true,
    skill: install,
    agentsMd,
    nextSteps: [
      "Confirm authorized hosts, endpoints, methods, identities, rate, budget, and test window.",
      "Run `scout init <spec> --base-url <url>`, then orient with `scout endpoints --json` and `scout schema ... --json`.",
      "Preview a filtered `scout sweep --dry-run`, execute it, then use `scout call`/`scout fuzz` and `scout report`.",
    ],
  };

  if (options.json || !isInteractive()) {
    console.log(stringifyJson(result));
    return;
  }

  if (install.installed) log.success(`Installed bundled ${SKILL_NAME} skill at ${install.path}.`);
  else log.info("Skipped skill installation.");
  if (agentsMd.written) log.success(`Updated ${agentsMd.path} with scout agent guidance.`);
  else if (agentsMd.skipped) log.info("Skipped AGENTS.md update.");
  log.info("Next: confirm authorized scope, then run `scout init <spec> --base-url <url>`.");
}

function installBundledSkill(cwd: string, source: string): AgentInitResult["skill"] {
  const path = join(cwd, ".agents", "skills", SKILL_NAME, "SKILL.md");
  mkdirSync(dirname(path), { recursive: true });
  copyFileSync(source, path);
  return { name: SKILL_NAME, path, installed: true, skipped: false };
}

function skippedSkillInstall(cwd: string): AgentInitResult["skill"] {
  return {
    name: SKILL_NAME,
    path: join(cwd, ".agents", "skills", SKILL_NAME, "SKILL.md"),
    installed: false,
    skipped: true,
  };
}

function skippedAgentsMd(cwd: string): AgentInitResult["agentsMd"] {
  return { path: join(cwd, "AGENTS.md"), written: false, skipped: true };
}

function writeLocalAgentsMd(cwd: string): AgentInitResult["agentsMd"] {
  const path = join(cwd, "AGENTS.md");
  const existing = existsSync(path) ? readFileSync(path, "utf-8") : null;
  const next = mergeScoutAgentsMd(existing);
  if (existing !== next) writeFileSync(path, next);
  return { path, written: existing !== next, skipped: false };
}

/** Merges the scout guidance block into AGENTS.md between stable markers. */
export function mergeScoutAgentsMd(existing: string | null): string {
  const block = buildScoutAgentsBlock();
  if (!existing || existing.trim() === "") return `# AGENTS.md\n\n${block}\n`;

  const startIdx = existing.indexOf(AGENTS_MD_START);
  if (startIdx !== -1) {
    const endIdx = existing.indexOf(AGENTS_MD_END, startIdx + AGENTS_MD_START.length);
    let before = existing.slice(0, startIdx);
    if (before.length > 0 && !before.endsWith("\n")) before += "\n";
    const after = endIdx === -1 ? "\n" : existing.slice(endIdx + AGENTS_MD_END.length);
    return `${before}${block}${after}`;
  }

  return `${existing.replace(/\s+$/, "")}\n\n${block}\n`;
}

function buildScoutAgentsBlock(): string {
  return [
    AGENTS_MD_START,
    "## Scout - API exploration",
    "",
    "This project can use scout to explore and test authorized APIs from an OpenAPI spec.",
    "",
    "- **Skill:** use the local `scout` skill for the full workflow; refresh it with `scout agent init`.",
    "- **Authorize:** confirm host, endpoints, methods, identities/tenants, test data, rate, budget, and test window before requests.",
    "- **Start:** `scout init <spec> --base-url <url>` starts an isolated run; `scout status --json` shows local state.",
    "- **Orient:** use `scout endpoints --json` and `scout schema <method> <path> --json`.",
    "- **Plan:** preview traffic with a filtered `scout sweep --dry-run --json`.",
    "- **Explore:** `scout call <method> <path> --json` only executes documented operations by default.",
    "- **Fuzz:** preview with `scout fuzz <method> <path> --dry-run --json`; execute only with mutation authorization and cleanup.",
    "- **Report:** validate candidate findings, then finish with `scout report --ci`.",
    AGENTS_MD_END,
  ].join("\n");
}

import { mkdtempSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import type { Command } from "commander";
import { describe, expect, it } from "vitest";
import { createProgram, isMainModule } from "./cli.js";

/** Returns a subcommand by name for help assertions. */
function getCommand(commandName: string) {
  const command = createProgram().commands.find((item) => item.name() === commandName);
  if (!command) {
    throw new Error(`Missing command: ${commandName}`);
  }
  return command;
}

/** Returns rendered help output including custom help text. */
function renderHelp(command: Command): string {
  let output = "";
  command.configureOutput({ writeOut: (value) => (output += value) });
  command.outputHelp();
  return output;
}

/** Returns a nested subcommand by name for help assertions. */
function getNestedCommand(command: Command, commandName: string): Command {
  const nested = command.commands.find((item) => item.name() === commandName);
  if (!nested) {
    throw new Error(`Missing command: ${command.name()} ${commandName}`);
  }
  return nested;
}

describe("CLI help", () => {
  it("documents the full command surface in root help", () => {
    const program = createProgram();
    const help = renderHelp(program);

    expect(help).toContain("Guardrailed API testing harness for coding agents.");
    const commandNames = program.commands.map((command) => command.name());
    for (const expected of [
      "init",
      "status",
      "reset",
      "endpoints",
      "schema",
      "call",
      "vars",
      "sweep",
      "fuzz",
      "coverage",
      "finding",
      "report",
      "agent",
    ]) {
      expect(commandNames).toContain(expected);
    }
  });

  it("documents the init workflow", () => {
    const help = renderHelp(getCommand("init"));
    expect(help).toContain("--base-url <url>");
    expect(help).toContain("--allow-mutations");
    expect(help).toContain("Authorization: Bearer $API_TOKEN");
  });

  it("documents call flags for exploration", () => {
    const help = renderHelp(getCommand("call"));
    expect(help).toContain("--path-param");
    expect(help).toContain("--data-stdin");
    expect(help).toContain("--raw-data <text>");
    expect(help).toContain("--raw-data-stdin");
    expect(help).toContain("--no-auth");
    expect(help).toContain("--invalid-auth");
    expect(help).toContain("--expect");
    expect(help).toContain("--allow-undocumented");
    expect(help).toContain("--auth-profile");
    expect(help).toContain("--fail-on-verdict");
  });

  it.each([
    ["--data", "{}", "--data-stdin"],
    ["--data", "{}", "--raw-data", "{"],
    ["--data-stdin", "--raw-data-stdin"],
    ["--raw-data", "x", "--raw-data-stdin"],
    ["--no-auth", "--invalid-auth"],
  ])("rejects conflicting call options: %s", async (...flags) => {
    const command = getCommand("call");
    command.exitOverride();
    command.configureOutput({ writeErr: () => {} });

    await expect(
      command.parseAsync(["GET", "/pets", ...flags], { from: "user" }),
    ).rejects.toMatchObject({ code: "commander.conflictingOption" });
  });

  it("documents sweep and report gates", () => {
    const sweep = renderHelp(getCommand("sweep"));
    expect(sweep).toContain("--no-auth-probes");
    expect(sweep).toContain("--dry-run");
    const report = renderHelp(getCommand("report"));
    expect(report).toContain("--ci");
    expect(report).toContain("--severity-threshold");
    expect(report).toContain("--min-coverage");
  });

  it("documents schema-driven fuzzing controls", () => {
    const help = renderHelp(getCommand("fuzz"));
    expect(help).toContain("--dry-run");
    expect(help).toContain("--data-stdin");
    expect(help).toContain("--max-cases");
    expect(help).toContain("--case");
    expect(help).toContain("--oversized-length");
    expect(help).toContain("may create side effects");
  });

  it("documents finding subcommands", () => {
    const finding = getCommand("finding");
    expect(getNestedCommand(finding, "add").description()).toContain("record a finding");
    expect(getNestedCommand(finding, "list").description()).toContain("list recorded findings");
    expect(getNestedCommand(finding, "confirm").description()).toContain("confirm a candidate");
    expect(getNestedCommand(finding, "dismiss").description()).toContain("dismiss a finding");
  });

  it("detects CLI execution through a symlinked bin path", () => {
    const dir = mkdtempSync(join(tmpdir(), "scout-cli-"));
    try {
      const target = join(dir, "cli.js");
      const link = join(dir, "scout");
      writeFileSync(target, "#!/usr/bin/env node\n");
      symlinkSync(target, link);

      expect(isMainModule(link, pathToFileURL(target).href)).toBe(true);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});

import { describe, expect, it } from "vitest";
import { computeCoverage } from "./coverage.js";
import type { RequestRecord } from "./session-store.js";
import type { SpecOperation } from "./spec-loader.js";

function op(method: SpecOperation["method"], path: string): SpecOperation {
  return {
    method,
    path,
    tags: [],
    deprecated: false,
    secured: false,
    authParameters: [],
    parameters: [],
    responses: {},
  };
}

function record(operation: string, schemaValid: RequestRecord["schemaValid"]): RequestRecord {
  return {
    id: "x",
    timestamp: "now",
    source: "call",
    operation,
    method: operation.split(" ")[0] ?? "GET",
    url: "https://x",
    status: 200,
    latencyMs: 1,
    schemaValid,
    requestHeaders: {},
  };
}

describe("computeCoverage", () => {
  const operations = [op("get", "/pets"), op("post", "/pets"), op("get", "/pets/{id}")];

  it("counts unexercised operations", () => {
    const summary = computeCoverage(operations, []);
    expect(summary.totalOperations).toBe(3);
    expect(summary.exercised).toBe(0);
    expect(summary.coveragePercent).toBe(0);
    expect(summary.requestTotals).toEqual({ recorded: 0, matched: 0, probes: 0 });
    expect(summary.untouched).toHaveLength(3);
  });

  it("marks called vs validated", () => {
    const summary = computeCoverage(operations, [
      record("GET /pets", true),
      record("POST /pets", "unknown"),
    ]);

    expect(summary.exercised).toBe(2);
    expect(summary.validated).toBe(1);
    expect(summary.coveragePercent).toBe(67);
    expect(summary.requestTotals).toEqual({ recorded: 2, matched: 2, probes: 0 });
    expect(summary.operations.find((o) => o.operation === "GET /pets")?.state).toBe("validated");
    expect(summary.operations.find((o) => o.operation === "GET /pets")).toMatchObject({
      controlCalls: 1,
      negativeCalls: 0,
      statuses: [200],
    });
    expect(summary.operations.find((o) => o.operation === "POST /pets")?.state).toBe("called");
    expect(summary.untouched).toEqual(["GET /pets/{id}"]);
  });

  it("does not treat negative probes as validated controls", () => {
    const negative = { ...record("GET /pets", true), source: "fuzz" as const };
    const summary = computeCoverage(operations, [negative]);
    expect(summary.operations.find((o) => o.operation === "GET /pets")).toMatchObject({
      state: "called",
      controlCalls: 0,
      negativeCalls: 1,
    });
  });
});

import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { createServer, type Server } from "node:http";
import type { AddressInfo } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

const spec = {
  openapi: "3.0.3",
  info: { title: "Broken Local API", version: "1.0.0" },
  paths: {
    "/items": {
      get: {
        operationId: "listItems",
        tags: ["items"],
        responses: {
          "200": {
            description: "ok",
            content: {
              "application/json": {
                schema: { type: "array", items: { type: "object" } },
              },
            },
          },
        },
      },
    },
    "/secure": {
      get: {
        operationId: "getSecure",
        tags: ["secure"],
        security: [{ bearer: [] }],
        responses: {
          "200": {
            description: "ok",
            content: {
              "application/json": {
                schema: { type: "object", properties: { ok: { type: "boolean" } } },
              },
            },
          },
        },
      },
    },
    "/boom": {
      get: {
        operationId: "getBoom",
        tags: ["boom"],
        responses: {
          "200": { description: "ok", content: { "application/json": { schema: {} } } },
        },
      },
    },
  },
  components: {
    securitySchemes: { bearer: { type: "http", scheme: "bearer" } },
  },
};

let server: Server;
let baseUrl: string;
let dir: string;
let originalCwd: string;

beforeAll(async () => {
  server = createServer((req, res) => {
    res.setHeader("content-type", "application/json");
    if (req.url === "/items") {
      res.statusCode = 200;
      res.end(JSON.stringify({ notAnArray: true }));
      return;
    }
    if (req.url === "/secure") {
      res.statusCode = 200; // returns 200 even without auth — the bug
      res.end(JSON.stringify({ ok: true }));
      return;
    }
    if (req.url === "/boom") {
      res.statusCode = 500;
      res.end(JSON.stringify({ error: "kaboom" }));
      return;
    }
    res.statusCode = 404;
    res.end(JSON.stringify({ error: "not found" }));
  });

  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const address = server.address() as AddressInfo;
  baseUrl = `http://127.0.0.1:${address.port}`;

  dir = mkdtempSync(join(tmpdir(), "scout-e2e-"));
  writeFileSync(join(dir, "openapi.json"), JSON.stringify(spec));
  originalCwd = process.cwd();
  process.chdir(dir);
});

afterAll(async () => {
  process.chdir(originalCwd);
  rmSync(dir, { recursive: true, force: true });
  await new Promise<void>((resolve, reject) =>
    server.close((error) => (error ? reject(error) : resolve())),
  );
});

describe("end-to-end sweep against a known-bad API", () => {
  it("init → sweep → report surfaces the planted bugs", async () => {
    const logs: string[] = [];
    vi.spyOn(console, "log").mockImplementation((value: unknown) => {
      logs.push(String(value));
    });

    const { runInitCommand } = await import("./init-command.js");
    const { runSweepCommand } = await import("./sweep-command.js");
    const { runReportCommand } = await import("./report-command.js");

    await runInitCommand("openapi.json", { baseUrl, json: true });
    const initResult = JSON.parse(logs.at(-1) as string);
    expect(initResult.operations).toBe(3);

    logs.length = 0;
    await runSweepCommand({ json: true });
    const sweep = JSON.parse(logs.at(-1) as string);

    const titles = sweep.findings.map((f: { title: string }) => f.title).join(" | ");
    expect(sweep.findingsCreated).toBeGreaterThanOrEqual(3);
    expect(titles).toMatch(/schema/i); // /items returns wrong shape
    expect(titles).toMatch(/without credentials/i); // /secure 2xx without auth
    expect(titles).toMatch(/500/); // /boom

    const authCandidate = sweep.findings.find(
      (f: { severity: string; category: string }) => f.severity === "high" && f.category === "auth",
    );
    expect(authCandidate).toBeDefined();

    logs.length = 0;
    await runReportCommand({ json: true, severityThreshold: "high" });
    const report = JSON.parse(logs.at(-1) as string);
    expect(report.summary.passed).toBe(false);
    expect(report.coverage.totalOperations).toBe(3);

    vi.restoreAllMocks();
  });
});

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

const fixture = fileURLToPath(new URL("./__fixtures__/petstore-min.json", import.meta.url));

let dir: string;
let originalCwd: string;

beforeAll(async () => {
  dir = mkdtempSync(join(tmpdir(), "scout-endpoints-"));
  originalCwd = process.cwd();
  process.chdir(dir);
  vi.spyOn(console, "log").mockImplementation(() => {});
  const { runInitCommand } = await import("./init-command.js");
  await runInitCommand(fixture, { baseUrl: "https://api.example.com", json: true });
  vi.restoreAllMocks();
});

afterAll(() => {
  process.chdir(originalCwd);
  rmSync(dir, { recursive: true, force: true });
});

const logs: string[] = [];
beforeEach(() => {
  logs.length = 0;
  vi.spyOn(console, "log").mockImplementation((v: unknown) => {
    logs.push(String(v));
  });
});

async function runEndpoints(options: Record<string, unknown>) {
  const { runEndpointsCommand } = await import("./endpoints-command.js");
  await runEndpointsCommand(options);
  vi.restoreAllMocks();
  return JSON.parse(logs.at(-1) as string);
}

describe("endpoints command", () => {
  it("lists all operations compactly when under the cap", async () => {
    const out = await runEndpoints({ json: true });
    expect(out.total).toBe(4);
    expect(out.shown).toBe(4);
    expect(out.truncated).toBe(false);
    // Compact rows omit empty fields.
    const getPet = out.operations.find((o: { path: string }) => o.path === "/pets/{petId}");
    expect(getPet.method).toBe("GET");
    expect(getPet).not.toHaveProperty("deprecated");
  });

  it("caps output and surfaces a tag overview + hint when truncated", async () => {
    const out = await runEndpoints({ json: true, limit: 2 });
    expect(out.total).toBe(4);
    expect(out.shown).toBe(2);
    expect(out.truncated).toBe(true);
    expect(out.tags).toBeDefined();
    expect(out.hint).toContain("--tag");
  });

  it("does not include a tag overview once narrowed by tag", async () => {
    const out = await runEndpoints({ json: true, limit: 1, tag: "pets" });
    expect(out.truncated).toBe(true);
    expect(out.tags).toBeUndefined();
  });

  it("shows everything with --all", async () => {
    const out = await runEndpoints({ json: true, limit: 1, all: true });
    expect(out.shown).toBe(4);
    expect(out.truncated).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import { isJsonOutputRequested, ScoutError, toJsonErrorEnvelope } from "./errors.js";

describe("CLI error envelopes", () => {
  it("detects JSON mode from argv", () => {
    expect(isJsonOutputRequested(["node", "scout", "status", "--json"])).toBe(true);
    expect(isJsonOutputRequested(["node", "scout", "status"])).toBe(false);
  });

  it("formats API status errors", () => {
    const error = new Error("Forbidden") as Error & { statusCode: number };
    error.statusCode = 403;

    expect(toJsonErrorEnvelope(error, 2)).toEqual({
      success: false,
      error: {
        code: "AUTH_FAILED",
        message:
          "Target API authentication failed. Check the selected auth profile or configured headers.",
        hint: "Check the target API credentials configured in scout.json and retry.",
        statusCode: 403,
      },
      exitCode: 2,
    });
  });

  it("carries explicit code and hint from ScoutError", () => {
    const error = new ScoutError("No scout session in this directory.", {
      code: "NO_SESSION",
      hint: "Run `scout init <spec>` first.",
    });

    expect(toJsonErrorEnvelope(error, 2)).toEqual({
      success: false,
      error: {
        code: "NO_SESSION",
        message: "No scout session in this directory.",
        hint: "Run `scout init <spec>` first.",
      },
      exitCode: 2,
    });
  });

  it("extracts status code from nested causes", () => {
    const inner = new Error("upstream") as Error & { statusCode: number };
    inner.statusCode = 429;
    const outer = new Error("wrapped", { cause: inner });

    expect(toJsonErrorEnvelope(outer, 2).error.statusCode).toBe(429);
  });
});

import { mkdirSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import {
  appendFinding,
  createFinding,
  parseCategory,
  parseSeverity,
  readFindings,
  severityRank,
  updateFindingStatus,
  validateFindingInput,
