describe("deterministic findings", () => {
  it("deduplicates repeated mechanical findings and preserves lifecycle status", () => {
    const cwd = mkdtempSync(join(tmpdir(), "scout-findings-"));
    mkdirSync(join(cwd, ".scout"));
    try {
      const input = {
        source: "sweep" as const,
        severity: "high" as const,
        category: "auth" as const,
        endpoint: "GET /admin",
        title: "Potential auth bypass",
        status: "candidate" as const,
      };
      const first = createFinding(input);
      const repeated = createFinding(input);

      expect(repeated.id).toBe(first.id);
      expect(appendFinding(first, cwd).created).toBe(true);
      expect(appendFinding(repeated, cwd).created).toBe(false);
      expect(readFindings(cwd)).toHaveLength(1);

      expect(updateFindingStatus(first.id, "dismissed", cwd).status).toBe("dismissed");
      expect(appendFinding(repeated, cwd).finding.status).toBe("dismissed");
      expect(readFindings(cwd)).toHaveLength(1);
    } finally {
      rmSync(cwd, { recursive: true, force: true });
    }
  });

  it("collapses the same contract issue across probe kinds (different repro)", () => {
    const cwd = mkdtempSync(join(tmpdir(), "scout-findings-"));
    mkdirSync(join(cwd, ".scout"));
    try {
      const base = {
        source: "sweep" as const,
        severity: "medium" as const,
        category: "contract-violation" as const,
        endpoint: "GET /v1/ai-gateway/rules",
        title: "Undocumented status 404",
      };
      // Same finding seen on happy-path, no-auth, invalid-auth probes.
      const a = createFinding({ ...base, repro: "scout call GET /v1/ai-gateway/rules" });
      const b = createFinding({ ...base, repro: "scout call GET /v1/ai-gateway/rules --no-auth" });
      const c = createFinding({
        ...base,
        repro: "scout call GET /v1/ai-gateway/rules --invalid-auth",
      });

      expect(b.id).toBe(a.id);
      expect(c.id).toBe(a.id);
      expect(appendFinding(a, cwd).created).toBe(true);
      expect(appendFinding(b, cwd).created).toBe(false);
      expect(appendFinding(c, cwd).created).toBe(false);
      expect(readFindings(cwd)).toHaveLength(1);
    } finally {
      rmSync(cwd, { recursive: true, force: true });
    }
  });

  it("records and clears a dismiss reason across transitions", () => {
    const cwd = mkdtempSync(join(tmpdir(), "scout-findings-"));
    mkdirSync(join(cwd, ".scout"));
    try {
      const finding = createFinding({
        source: "sweep",
        severity: "high",
        category: "auth",
        endpoint: "GET /admin",
        title: "Potential auth bypass",
      });
      appendFinding(finding, cwd);

      const dismissed = updateFindingStatus(finding.id, "dismissed", cwd, undefined, "known WIP");
      expect(dismissed.dismissReason).toBe("known WIP");

      const reconfirmed = updateFindingStatus(finding.id, "confirmed", cwd);
      expect(reconfirmed.dismissReason).toBeUndefined();
    } finally {
      rmSync(cwd, { recursive: true, force: true });
    }
  });

  it("throws when lifecycle id is unknown", () => {
    const cwd = mkdtempSync(join(tmpdir(), "scout-findings-"));
    mkdirSync(join(cwd, ".scout"));
    try {
      expect(() => updateFindingStatus("missing", "confirmed", cwd)).toThrow(/not found/);
    } finally {
      rmSync(cwd, { recursive: true, force: true });
    }
  });
});

import { ScoutError } from "./errors.js";
import { scopeOperations } from "./operation-filter.js";
import { stringifyJson } from "./output.js";
import { loadProjectConfigOrThrow, resolvePolicy } from "./project-config.js";
import { loadCachedSpec } from "./session-store.js";
import { extractOperations, operationKey, parseHttpMethodArg } from "./spec-loader.js";

const DEFAULT_DEPTH = 6;

export type SchemaOptions = {
  json?: boolean;
  depth?: number;
  full?: boolean;
};

/**
 * Caps a fully-dereferenced schema at a nesting depth, replacing deeper
 * objects/arrays with a placeholder. Dereferencing inlines every $ref, so a
 * single operation on a large API (e.g. GitHub) can be tens of thousands of
 * tokens — this keeps the slice context-friendly. `--full` disables it.
 */
export function capDepth(value: unknown, maxDepth: number): { value: unknown; truncated: boolean } {
  let truncated = false;

  function walk(node: unknown, depth: number): unknown {
    if (Array.isArray(node)) {
      if (depth >= maxDepth && node.length > 0) {
        truncated = true;
        return "[…array — use --full]";
      }
      return node.map((item) => walk(item, depth + 1));
    }
    if (node && typeof node === "object") {
      const entries = Object.entries(node as Record<string, unknown>);
      if (depth >= maxDepth && entries.length > 0) {
        truncated = true;
        return "[…object — use --full]";
      }
      const out: Record<string, unknown> = {};
      for (const [key, val] of entries) {
        out[key] = walk(val, depth + 1);
      }
      return out;
    }
    return node;
  }

  return { value: walk(value, 0), truncated };
}

/** Prints the full schema detail for a single operation. */
export async function runSchemaCommand(
  method: string,
  path: string,
  options: SchemaOptions,
): Promise<void> {
  const loadedSpec = loadCachedSpec();
  const { config } = loadProjectConfigOrThrow();
  const operations = scopeOperations(extractOperations(loadedSpec.spec), resolvePolicy(config));
  const normalizedMethod = parseHttpMethodArg(method);

  const operation = operations.find((op) => op.method === normalizedMethod && op.path === path);

  if (!operation) {
    throw new ScoutError(`Operation ${method.toUpperCase()} ${path} not found in spec.`, {
      code: "NOT_FOUND",
      hint: "Run `scout endpoints --json` to list exact method/path pairs.",
    });
  }

  const maxDepth = options.full ? Number.POSITIVE_INFINITY : (options.depth ?? DEFAULT_DEPTH);
  const params = capDepth(operation.parameters, maxDepth);
  const requestBody = capDepth(operation.requestBody ?? null, maxDepth);
  const responses = capDepth(operation.responses, maxDepth);
  const truncated = params.truncated || requestBody.truncated || responses.truncated;

  const detail = {
    operation: operationKey(operation),
    operationId: operation.operationId ?? null,
    summary: operation.summary ?? null,
    description: operation.description ?? null,
    tags: operation.tags,
    deprecated: operation.deprecated,
    secured: operation.secured,
    authParameters: operation.authParameters,
    parameters: params.value,
    requestBody: requestBody.value,
    responses: responses.value,
    ...(truncated
      ? { truncated: true, hint: "Schema capped at depth for context. Pass --full for everything." }
      : {}),
  };

  console.log(stringifyJson(detail));
}

