import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { readFindings } from "./findings.js";
import { runFuzzCommand } from "./fuzz-command.js";
import { runInitCommand } from "./init-command.js";
import { readRequestRecords } from "./session-store.js";

const fixture = fileURLToPath(new URL("./__fixtures__/petstore-min.json", import.meta.url));

describe("fuzz command", () => {
  let cwd: string;
  let originalCwd: string;
  let logs: string[];

  beforeEach(async () => {
    cwd = mkdtempSync(join(tmpdir(), "scout-fuzz-"));
    originalCwd = process.cwd();
    process.chdir(cwd);
    logs = [];
    vi.spyOn(console, "log").mockImplementation((value: unknown) => logs.push(String(value)));
    await runInitCommand(fixture, {
      baseUrl: "https://api.example.com",
      allowMutations: true,
      json: true,
    });
    logs.length = 0;
  });

  afterEach(() => {
    process.chdir(originalCwd);
    rmSync(cwd, { recursive: true, force: true });
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it("previews generated cases without sending requests", async () => {
    const fetchMock = vi.fn();
    vi.stubGlobal("fetch", fetchMock);

    await runFuzzCommand("POST", "/pets", { dryRun: true, maxCases: 8, json: true });

    const output = JSON.parse(logs.at(-1) as string);
    expect(output.operation).toBe("POST /pets");
    expect(output.baseline).toBe("generated");
    expect(output.generatedBaseline).toEqual({ id: 0, name: "s" });
    expect(output.casesPlanned).toBe(8);
    expect(
      output.cases.some((fuzzCase: { kind: string }) => fuzzCase.kind === "malformed-json"),
    ).toBe(true);
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it("rejects an invalid supplied baseline before requests", async () => {
    const fetchMock = vi.fn();
    vi.stubGlobal("fetch", fetchMock);

    await expect(
      runFuzzCommand("POST", "/pets", { data: "{}", dryRun: true, json: true }),
    ).rejects.toMatchObject({ code: "VALIDATION_ERROR" });
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it("selects one stable dry-run case for reproduction", async () => {
    vi.stubGlobal("fetch", vi.fn());
    await runFuzzCommand("POST", "/pets", { dryRun: true, maxCases: 8, json: true });
    const first = JSON.parse(logs.at(-1) as string).cases[0] as { id: string };
    logs.length = 0;

    await runFuzzCommand("POST", "/pets", { dryRun: true, case: first.id, json: true });

    const output = JSON.parse(logs.at(-1) as string);
    expect(output.casesPlanned).toBe(1);
    expect(output.cases).toMatchObject([{ id: first.id }]);
  });

  it("executes malformed and schema-invalid cases and records candidates", async () => {
    const fetchMock = vi.fn(async (_input: URL | RequestInfo, init?: RequestInit) => {
      if (init?.body === '{"__scout_malformed":') {
        return new Response(JSON.stringify({ error: "invalid json" }), {
          status: 400,
          headers: { "Content-Type": "application/json" },
        });
      }
      return new Response(JSON.stringify({ id: 1, name: "created" }), {
        status: 201,
        headers: { "Content-Type": "application/json" },
      });
    });
    vi.stubGlobal("fetch", fetchMock);

    await runFuzzCommand("POST", "/pets", { maxCases: 2, json: true });

    const output = JSON.parse(logs.at(-1) as string);
    expect(output.casesRun).toBe(2);
    expect(
      output.findings.some((finding: { title: string }) => /invalid-input/.test(finding.title)),
    ).toBe(true);
    expect(readFindings(cwd).some((finding) => finding.source === "fuzz")).toBe(true);
    expect(readRequestRecords(cwd).map((record) => record.source)).toEqual(["fuzz", "fuzz"]);
  });

  it("stops immediately on rate limiting without recording a contract finding", async () => {
    const fetchMock = vi.fn(
      async () =>
        new Response(JSON.stringify({ error: "slow down" }), {
          status: 429,
          headers: { "Content-Type": "application/json" },
        }),
    );
    vi.stubGlobal("fetch", fetchMock);

    await runFuzzCommand("POST", "/pets", { maxCases: 5, json: true });

    const output = JSON.parse(logs.at(-1) as string);
    expect(output.casesRun).toBe(1);
    expect(output.stoppedReason).toBe("rate-limited");
    expect(output.findings).toEqual([]);
  });

  it("returns a zero-run summary when the session budget is exhausted", async () => {
    const configPath = join(cwd, "scout.json");
    const config = JSON.parse(readFileSync(configPath, "utf-8"));
    config.policy.budget = 1;
    writeFileSync(configPath, JSON.stringify(config));
    const fetchMock = vi.fn(
      async () =>
        new Response(JSON.stringify({ error: "invalid" }), {
          status: 400,
          headers: { "Content-Type": "application/json" },
        }),
    );
    vi.stubGlobal("fetch", fetchMock);

    await runFuzzCommand("POST", "/pets", { maxCases: 1, json: true });
    logs.length = 0;
    fetchMock.mockClear();
    await runFuzzCommand("POST", "/pets", { maxCases: 5, json: true });

    const output = JSON.parse(logs.at(-1) as string);
    expect(output.casesRun).toBe(0);
    expect(output.stoppedReason).toBe("budget-limited");
    expect(fetchMock).not.toHaveBeenCalled();
  });
});

import { describe, expect, it } from "vitest";
import {
  evaluateFuzzCase,
  generateBaselineValue,
  planFuzzCases,
  selectJsonRequestSchema,
  type FuzzCase,
} from "./fuzz-engine.js";
import type { CallResult } from "./http-executor.js";
import type { SpecOperation } from "./spec-loader.js";

const requestSchema = {
  type: "object",
  additionalProperties: false,
  required: ["name", "age", "tags"],
  properties: {
    name: { type: "string", minLength: 2, maxLength: 8 },
    age: { type: "integer", minimum: 18, maximum: 120 },
    tags: { type: "array", minItems: 1, maxItems: 2, items: { type: "string" } },
    role: { type: "string", enum: ["user", "admin"] },
  },
} as const;

/** Creates one request-body operation for fuzz tests. */
function operation(schema: unknown = requestSchema): SpecOperation {
  return {
    method: "post",
    path: "/users",
    tags: [],
    deprecated: false,
    secured: false,
    authParameters: [],
    parameters: [],
    requestBody: {
      required: true,
      content: { "application/json": { schema } },
    },
    responses: { "400": { description: "invalid" } },
  };
}

/** Creates a minimal call result for fuzz finding evaluation. */
function result(status: number, verdict: Partial<CallResult["verdict"]> = {}): CallResult {
  return {
    requestId: "request-id",
    operation: "POST /users",
    request: { method: "POST", url: "https://api.example.com/users", headers: {} },
    response: { status, headers: {}, body: {}, bodyIsJson: true, bodyTruncated: false },
    verdict: {
      ok: true,
      summary: "PASS",
      status,
      expectedStatuses: ["400"],
      statusExpected: true,
      schemaValid: true,
      schemaErrors: [],
      contentTypeMatch: true,
      latencyMs: 5,
      redacted: false,
      ...verdict,
    },
  };
}

describe("request schema selection", () => {
  it("selects JSON and structured JSON media types", () => {
    expect(selectJsonRequestSchema(operation())).toEqual(requestSchema);
    expect(
      selectJsonRequestSchema({
        ...operation(),
        requestBody: {
          required: true,
          content: { "application/problem+json": { schema: { type: "string" } } },
        },
      }),
    ).toEqual({ type: "string" });
  });

  it("returns null without a JSON request schema", () => {
    expect(
      selectJsonRequestSchema({
        ...operation(),
        requestBody: { required: true, content: { "text/plain": { schema: {} } } },
      }),
    ).toBeNull();
  });

  it("removes readOnly properties from request requirements", () => {
    const schema = selectJsonRequestSchema(
      operation({
        type: "object",
        required: ["id", "name"],
        properties: {
          id: { type: "integer", readOnly: true },
          name: { type: "string" },
        },
      }),
    );
    expect(schema?.required).toEqual(["name"]);
    expect(generateBaselineValue(schema ?? {})).toEqual({ name: "s" });
  });

  it("removes cross-branch allOf readOnly requirements", () => {
    const schema = selectJsonRequestSchema(
      operation({
        allOf: [
          { type: "object", required: ["id", "name"] },
          {
            type: "object",
            properties: {
              id: { type: "integer", readOnly: true },
              name: { type: "string" },
            },
          },
        ],
      }),
    );
    expect(generateBaselineValue(schema ?? {})).toEqual({ name: "s" });
  });

  it("supports OpenAPI 3.1 boolean request schemas", () => {
    expect(selectJsonRequestSchema(operation(true))).toBe(true);
    expect(planFuzzCases(true, {}, { maxCases: 10 })).toMatchObject([{ kind: "malformed-json" }]);
    expect(selectJsonRequestSchema(operation(false))).toBe(false);
  });
});

describe("generateBaselineValue", () => {
  it("generates required fields at valid lower boundaries", () => {
    expect(generateBaselineValue(requestSchema)).toEqual({
      name: "ss",
      age: 18,
      tags: ["s"],
    });
  });

  it("uses deterministic format-safe values", () => {
    expect(generateBaselineValue({ type: "string", format: "email" })).toBe(
      "scout@example.invalid",
    );
    expect(generateBaselineValue({ type: "string", format: "uuid" })).toMatch(/^[0-9a-f-]{36}$/);
  });
});

describe("planFuzzCases", () => {
  it("generates the negative input matrix", () => {
    const baseline = generateBaselineValue(requestSchema);
    const cases = planFuzzCases(requestSchema, baseline, {
      maxCases: 50,
      oversizedLength: 32,
    });
    const kinds = new Set(cases.map((fuzzCase) => fuzzCase.kind));

    expect(kinds).toEqual(
      new Set([
        "malformed-json",
        "null",
        "wrong-type",
        "missing-required",
        "boundary",
        "oversized",
        "unknown-field",
        "enum",
      ]),
    );
    expect(cases.find((fuzzCase) => fuzzCase.id === "below-minimum-age")?.body).toMatchObject({
      age: 17,
    });
    expect(cases.find((fuzzCase) => fuzzCase.id === "unknown-field-root")?.expectedReject).toBe(
      true,
    );
    expect(cases.find((fuzzCase) => fuzzCase.id === "oversized-name")?.expectedReject).toBe(true);
  });

  it("caps cases and marks unbounded oversized inputs as exploratory", () => {
    const schema = { type: "object", properties: { note: { type: "string" } } };
    expect(planFuzzCases(schema, {}, { maxCases: 3 })).toHaveLength(3);

    const cases = planFuzzCases(schema, {}, { maxCases: 10, oversizedLength: 12 });
    expect(cases.find((fuzzCase) => fuzzCase.kind === "oversized")?.expectedReject).toBe(false);
  });

  it("validates cases against union and nullable schemas", () => {
    const unionCases = planFuzzCases({ type: ["string", "number"] }, "s", { maxCases: 10 });
    expect(unionCases.some((fuzzCase) => fuzzCase.id === "wrong-type-root")).toBe(false);

    const nullableCases = planFuzzCases({ oneOf: [{ type: "string" }, { type: "null" }] }, "s", {
      maxCases: 10,
    });
    expect(nullableCases.some((fuzzCase) => fuzzCase.id === "null-root")).toBe(false);
  });

  it("traverses a representative nested array item", () => {
    const schema = {
      type: "object",
      required: ["items"],
      properties: {
        items: {
          type: "array",
          minItems: 1,
          items: {
            type: "object",
            required: ["name"],
            properties: { name: { type: "string" } },
          },
        },
      },
    };
    const cases = planFuzzCases(schema, generateBaselineValue(schema), { maxCases: 50 });
    expect(cases.some((fuzzCase) => fuzzCase.id === "missing-required-items-0-name")).toBe(true);
  });

  it("does not mutate prototypes for adversarial property names", () => {
    const schema = JSON.parse(
      '{"type":"object","required":["__proto__"],"properties":{"__proto__":{"type":"object","required":["polluted"],"properties":{"polluted":{"type":"string"}}}}}',
    );
    const baseline = generateBaselineValue(schema) as Record<string, unknown>;
    expect(Object.prototype).not.toHaveProperty("polluted");
    expect(Object.prototype.hasOwnProperty.call(baseline, "__proto__")).toBe(true);

    planFuzzCases(schema, baseline, { maxCases: 20 });
    expect(Object.prototype).not.toHaveProperty("polluted");
  });

  it("enforces hard case and body-size limits", () => {
    const manyProperties = Object.fromEntries(
      Array.from({ length: 200 }, (_, index) => [`field${index}`, { type: "string" }]),
    );
    const cases = planFuzzCases(
      { type: "object", properties: manyProperties },
      {},
      { maxCases: 10_000 },
    );
    expect(cases.length).toBeLessThanOrEqual(100);
    expect(() => planFuzzCases({ type: "string" }, "x".repeat(256 * 1024 + 1))).toThrow(/exceeds/);
  });
});

describe("evaluateFuzzCase", () => {
  const fuzzCase: FuzzCase = {
    id: "wrong-type-name",
    kind: "wrong-type",
    title: "Wrong type at /name",
    target: "/name",
    expectedReject: true,
    body: { name: 123 },
  };

  it("records accepted schema-invalid input as a candidate", () => {
    const findings = evaluateFuzzCase(operation(), fuzzCase, result(201));
    expect(findings.some((finding) => finding.title.includes("Potential invalid-input"))).toBe(
      true,
    );
    expect(findings[0]?.source).toBe("fuzz");
    expect(findings.find((finding) => finding.title.includes("Potential"))?.status).toBe(
      "candidate",
    );
  });

  it("records 5xx and malformed response contracts", () => {
    const findings = evaluateFuzzCase(
      operation(),
      fuzzCase,
      result(500, { statusExpected: false, schemaValid: false, contentTypeMatch: false }),
    );
    expect(findings.some((finding) => finding.category === "error-handling")).toBe(true);
    expect(findings.some((finding) => finding.title.includes("schema mismatch"))).toBe(true);
    expect(findings.some((finding) => finding.title.includes("content type"))).toBe(true);
  });

  it("does not flag a documented 4xx with a valid response", () => {
    expect(evaluateFuzzCase(operation(), fuzzCase, result(400))).toEqual([]);
  });
});

import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { MAX_RESPONSE_DOWNLOAD_BYTES, MAX_RESPONSE_PREVIEW_BYTES } from "./constants.js";
import {
  encodeFormBody,
  executeCall,
  matchOperation,
  RateLimiter,
  resolveEnvRefs,
  selectRequestContentType,
  type ExecutorContext,
} from "./http-executor.js";
import type { SpecOperation } from "./spec-loader.js";

function op(method: SpecOperation["method"], path: string): SpecOperation {
  return {
    method,
    path,
    tags: [],
    deprecated: false,
    secured: false,
    authParameters: [],
    parameters: [],
    responses: {},
  };
}

const operations = [op("get", "/pets"), op("get", "/pets/{petId}"), op("post", "/pets")];

/** Creates a minimal executor context backed by a temporary session. */
function createTestContext(
  cwd: string,
  headers: Record<string, string> = {},
  operationList: SpecOperation[] = operations,
): ExecutorContext {
  const sessionDir = join(cwd, ".scout");
  mkdirSync(sessionDir);
  writeFileSync(
    join(sessionDir, "state.json"),
    JSON.stringify({
      specSource: "test",
      specHash: "test",
      createdAt: new Date(0).toISOString(),
      requestCount: 0,
    }),
  );

  return {
    cwd,
    config: { spec: "test", baseUrl: "https://api.example.com", headers },
    policy: { allowMutations: true, rateLimit: 5, budget: 20 },
    loadedSpec: {
      spec: { openapi: "3.1.0", paths: {} },
      source: "test",
      hash: "test",
      title: "Test",
      version: "1",
      specVersion: "3.1.0",
      converted: false,
      dereferenced: true,
      warnings: [],
    },
    operations: operationList,
  };
}

describe("matchOperation", () => {
  it("matches an exact template path", () => {
    const match = matchOperation(operations, "get", "/pets/{petId}");
    expect(match?.operation.path).toBe("/pets/{petId}");
    expect(match?.extractedPathParams).toEqual({});
  });

  it("matches a concrete path and extracts params", () => {
    const match = matchOperation(operations, "get", "/pets/42");
    expect(match?.operation.path).toBe("/pets/{petId}");
    expect(match?.extractedPathParams).toEqual({ petId: "42" });
  });

  it("respects method", () => {
    expect(matchOperation(operations, "delete", "/pets")).toBeNull();
  });

  it("returns null for unknown paths", () => {
    expect(matchOperation(operations, "get", "/unknown/thing/deep")).toBeNull();
  });
});

