    expect(normalResult.response.body).toEqual({
      cookie: "session=[redacted]; theme=[redacted]",
      token: "[redacted]",
      theme: "[redacted]",
    });
  });

  it("removes only declared auth cookies without resolving their env refs", async () => {
    const fetchMock = vi.fn(async () => new Response("{}", { status: 200 }));
    vi.stubGlobal("fetch", fetchMock);
    const securedOperation = op("get", "/pets");
    securedOperation.secured = true;
    securedOperation.authParameters = [{ name: "session", in: "cookie" }];

    await executeCall(
      createTestContext(cwd, { Cookie: "session=$SCOUT_UNSET_COOKIE_TOKEN; theme=dark" }, [
        securedOperation,
      ]),
      { method: "get", path: "/pets", source: "call", noAuth: true },
    );

    const init = fetchMock.mock.calls[0]?.[1] as RequestInit;
    expect(new Headers(init.headers).get("Cookie")).toBe("theme=dark");
  });

  it("does not strip benign names containing key", async () => {
    const fetchMock = vi.fn(async () => new Response("{}", { status: 200 }));
    vi.stubGlobal("fetch", fetchMock);

    const result = await executeCall(createTestContext(cwd), {
      method: "get",
      path: "/pets",
      source: "call",
      noAuth: true,
      query: { monkey: "banana" },
      headers: { Keyboard: "compact" },
    });

    const [input, init] = fetchMock.mock.calls[0] as unknown as [URL, RequestInit];
    expect(input.toString()).toBe("https://api.example.com/pets?monkey=banana");
    expect(new Headers(init.headers).get("Keyboard")).toBe("compact");
    expect(result.request.headers.Keyboard).toBe("compact");
  });

  it("redacts literal credential values recursively from parsed responses", async () => {
    const fetchMock = vi.fn(
      async () =>
        new Response(
          JSON.stringify({ token: "[REDACTED]", nested: ["Bearer literal-secret", "safe"] }),
          { status: 200, headers: { "Content-Type": "application/json" } },
        ),
    );
    vi.stubGlobal("fetch", fetchMock);

    const result = await executeCall(createTestContext(cwd), {
      method: "get",
      path: "/pets",
      source: "call",
      headers: { Authorization: "Bearer literal-secret" },
    });

    expect(result.response.body).toEqual({
      token: "[redacted]",
      nested: ["[redacted]", "safe"],
    });
  });

  it("redacts real credentials containing the synthetic marker text", async () => {
    const credential = "[REDACTED]";
    const fetchMock = vi.fn(
      async () =>
        new Response(JSON.stringify({ credential }), {
          status: 200,
          headers: { "Content-Type": "application/json" },
        }),
    );
    vi.stubGlobal("fetch", fetchMock);

    const result = await executeCall(createTestContext(cwd), {
      method: "get",
      path: "/pets",
      source: "call",
      headers: { Authorization: credential },
    });

    expect(result.request.headers.Authorization).toBe("[redacted]");
    expect(result.response.body).toEqual({ credential: "[redacted]" });
  });

  it("omits fuzz bodies and redacts echoed secret-like fields", async () => {
    const secret = 'super-"secret\\value';
    const fetchMock = vi.fn(
      async () =>
        new Response(JSON.stringify({ password: secret, safe: "visible" }), {
          status: 200,
          headers: { "Content-Type": "application/json" },
        }),
    );
    vi.stubGlobal("fetch", fetchMock);

    const result = await executeCall(createTestContext(cwd), {
      method: "post",
      path: "/pets",
      source: "fuzz",
      body: { password: secret, name: "scout" },
      redactBodyEvidence: true,
    });

    expect(result.request.body).toBe("[redacted fuzz body]");
    expect(result.response.body).toEqual({ password: "[redacted]", safe: "visible" });
    const record = JSON.parse(readFileSync(join(cwd, ".scout", "requests.jsonl"), "utf-8"));
    expect(record.requestBody).toBe("[redacted fuzz body]");
    expect(record.responseBody).not.toContain("super-");
  });

  it("preserves raw JSON response evidence outside fuzz redaction", async () => {
    const fetchMock = vi.fn(
      async () =>
        new Response('{"large":9007199254740993,"exponent":1e3}', {
          status: 200,
          headers: { "Content-Type": "application/json" },
        }),
    );
    vi.stubGlobal("fetch", fetchMock);

    await executeCall(createTestContext(cwd), {
      method: "get",
      path: "/pets",
      source: "call",
    });

    const record = JSON.parse(readFileSync(join(cwd, ".scout", "requests.jsonl"), "utf-8"));
    expect(record.responseBody).toBe('{"large":9007199254740993,"exponent":1e3}');
  });
});

describe("executeCall response surface", () => {
  let cwd: string;

  beforeEach(() => {
    cwd = mkdtempSync(join(tmpdir(), "scout-executor-"));
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    rmSync(cwd, { recursive: true, force: true });
  });

  it("captures all response headers and masks credential-like ones", async () => {
    const fetchMock = vi.fn(
      async () =>
        new Response("{}", {
          status: 200,
          headers: {
            "Content-Type": "application/json",
            Server: "Vercel",
            "X-Powered-By": "Next.js",
            "Set-Cookie": "session=supersecret; HttpOnly",
            Authorization: "Bearer leaked-token",
          },
        }),
    );
    vi.stubGlobal("fetch", fetchMock);

    const result = await executeCall(createTestContext(cwd), {
      method: "get",
      path: "/pets",
      source: "call",
    });

    expect(result.response.headers.server).toBe("Vercel");
    expect(result.response.headers["x-powered-by"]).toBe("Next.js");
    expect(result.response.headers["set-cookie"]).toBe("session=[redacted]; HttpOnly");
    expect(result.response.headers.authorization).toBe("[redacted]");

    const record = JSON.parse(readFileSync(join(cwd, ".scout", "requests.jsonl"), "utf-8"));
    expect(record.responseHeaders.server).toBe("Vercel");
    expect(record.responseHeaders["set-cookie"]).toBe("session=[redacted]; HttpOnly");
  });

  it("redacts the tester's own secret when echoed in a benign response header", async () => {
    const fetchMock = vi.fn(
      async () =>
        new Response("{}", {
          status: 200,
          headers: { "Content-Type": "application/json", "X-Echo": "raw-secret" },
        }),
    );
    vi.stubGlobal("fetch", fetchMock);

    const result = await executeCall(
      createTestContext(cwd, { Authorization: "Bearer raw-secret" }),
      { method: "get", path: "/pets", source: "call" },
    );

    expect(result.response.headers["x-echo"]).toBe("[redacted]");
  });

  it("returns the full response body without truncation and flags it complete", async () => {
    const big = "x".repeat(50_000);
    const fetchMock = vi.fn(async () => new Response(big, { status: 200 }));
    vi.stubGlobal("fetch", fetchMock);

    const result = await executeCall(createTestContext(cwd), {
      method: "get",
      path: "/pets",
      source: "call",
    });

    expect(typeof result.response.body).toBe("string");
    expect((result.response.body as string).length).toBe(50_000);
    expect(result.response.body).not.toContain("[truncated]");
    expect(result.response.bodyTruncated).toBe(false);
  });

  it("surfaces undocumented response fields in full so leaks stay visible", async () => {
    const fetchMock = vi.fn(
      async () =>
        new Response(
          JSON.stringify({ id: "1", internalDebugToken: "[REDACTED]", ssn: "123-45-6789" }),
          { status: 200, headers: { "Content-Type": "application/json" } },
        ),
    );
    vi.stubGlobal("fetch", fetchMock);

    const result = await executeCall(createTestContext(cwd), {
      method: "get",
      path: "/pets",
      source: "call",
    });

    expect(result.response.body).toEqual({
      id: "1",
      internalDebugToken: "[REDACTED]",
      ssn: "123-45-6789",
    });
    expect(result.response.bodyTruncated).toBe(false);
  });

  it("cancels response streaming beyond the download byte limit", async () => {
    let chunk = 0;
    const cancel = vi.fn();
    const stream = new ReadableStream<Uint8Array>({
      pull(controller) {
        chunk += 1;
        controller.enqueue(
          chunk === 1 ? new Uint8Array(MAX_RESPONSE_DOWNLOAD_BYTES) : new Uint8Array([120]),
        );
      },
      cancel,
    });
    vi.stubGlobal(
      "fetch",
      vi.fn(async () => new Response(stream, { status: 200 })),
    );

    const result = await executeCall(createTestContext(cwd), {
      method: "get",
      path: "/pets",
      source: "call",
    });

    expect(cancel).toHaveBeenCalledOnce();
    expect(result.response.bodyTruncated).toBe(true);
    expect(new TextEncoder().encode(result.response.body as string).byteLength).toBe(
      MAX_RESPONSE_PREVIEW_BYTES,
    );
  });

  it("returns a bounded preview instead of a large parsed JSON value", async () => {
    const raw = JSON.stringify({ values: ["x".repeat(MAX_RESPONSE_PREVIEW_BYTES)] });
    vi.stubGlobal(
      "fetch",
      vi.fn(
        async () =>
          new Response(raw, { status: 200, headers: { "Content-Type": "application/json" } }),
      ),
    );

    const result = await executeCall(createTestContext(cwd), {
      method: "get",
      path: "/pets",
      source: "call",
    });

    expect(result.response.bodyIsJson).toBe(true);
    expect(typeof result.response.body).toBe("string");
    expect(result.response.bodyTruncated).toBe(true);
    expect(new TextEncoder().encode(result.response.body as string).byteLength).toBeLessThanOrEqual(
      MAX_RESPONSE_PREVIEW_BYTES,
    );
  });
});

import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { loadProjectConfig } from "./project-config.js";
import { loadSessionState } from "./session-store.js";

/** Creates a minimal OpenAPI spec with a distinct default server. */
const spec = (title: string, server: string) => ({
  openapi: "3.1.0",
  info: { title, version: "1.0.0" },
  servers: [{ url: server }],
  paths: {},
});

describe("init run isolation", () => {
  let cwd: string;
  let originalCwd: string;

  beforeEach(() => {
    cwd = mkdtempSync(join(tmpdir(), "scout-init-"));
    originalCwd = process.cwd();
    process.chdir(cwd);
    writeFileSync(join(cwd, "first.json"), JSON.stringify(spec("First", "https://first.test")));
    writeFileSync(join(cwd, "second.json"), JSON.stringify(spec("Second", "https://second.test")));
    vi.spyOn(console, "log").mockImplementation(() => {});
  });

  afterEach(() => {
    vi.restoreAllMocks();
    process.chdir(originalCwd);
    rmSync(cwd, { recursive: true, force: true });
  });

  it("does not inherit target or safety config when a new spec is supplied", async () => {
    const { runInitCommand } = await import("./init-command.js");
    await runInitCommand("first.json", {
      baseUrl: "https://override.test",
      header: ["X-Test: old"],
      allowMutations: true,
      json: true,
    });

    await runInitCommand("second.json", { json: true });

    expect(loadProjectConfig()?.config).toEqual({
      $schema: "https://tester.army/scout.schema.json",
      spec: "second.json",
      baseUrl: "https://second.test",
      policy: { allowMutations: false },
    });
  });

  it("preserves config but starts a clean run during bare hydration", async () => {
    const { runInitCommand } = await import("./init-command.js");
    await runInitCommand("first.json", {
      header: ["X-Test: kept"],
      json: true,
    });
    const firstRun = loadSessionState();
    writeFileSync(join(cwd, ".scout", "requests.jsonl"), "old run\n");
    const configBefore = readFileSync(join(cwd, "scout.json"), "utf-8");

    await runInitCommand(undefined, { json: true });

    const hydratedResult = JSON.parse(vi.mocked(console.log).mock.calls.at(-1)?.[0] as string) as {
      runId: string;
    };
    expect(hydratedResult.runId).not.toBe(firstRun.runId);
    expect(loadSessionState().runId).toBe(hydratedResult.runId);
    expect(loadSessionState().requestCount).toBe(0);
    expect(readFileSync(join(cwd, "scout.json"), "utf-8")).toBe(configBefore);
    expect(() => readFileSync(join(cwd, ".scout", "requests.jsonl"), "utf-8")).toThrow();
  });

  it("does not persist empty scope arrays when only one scope flag is provided", async () => {
    const { runInitCommand } = await import("./init-command.js");
    await runInitCommand("first.json", { allowMethod: ["get"], json: true });

    expect(loadProjectConfig()?.config.policy).toEqual({
      allowMutations: false,
      allowedMethods: ["GET"],
    });
  });

  it("persists --max-spec-mb as maxSpecBytes so hydration reuses the cap", async () => {
    const { runInitCommand } = await import("./init-command.js");
    await runInitCommand("first.json", { maxSpecMb: 40, json: true });

    expect(loadProjectConfig()?.config.maxSpecBytes).toBe(40 * 1024 * 1024);
  });
});

describe("resolveMaxSpecBytes", () => {
  it("converts MiB to bytes and prefers the flag over persisted config", async () => {
    const { resolveMaxSpecBytes } = await import("./init-command.js");
    expect(resolveMaxSpecBytes({ maxSpecMb: 10 }, { baseUrl: "x", maxSpecBytes: 999 })).toBe(
      10 * 1024 * 1024,
    );
    expect(resolveMaxSpecBytes({}, { baseUrl: "x", maxSpecBytes: 999 })).toBe(999);
    expect(resolveMaxSpecBytes({}, undefined)).toBeUndefined();
  });

  it("rejects a value above the hard ceiling", async () => {
    const { resolveMaxSpecBytes } = await import("./init-command.js");
    expect(() => resolveMaxSpecBytes({ maxSpecMb: 1000 }, undefined)).toThrowError(
      /between 1 and 100/,
    );
  });
});

import { describe, expect, it } from "vitest";
import { extractPath, stringifyExtracted } from "./json-path.js";

describe("extractPath", () => {
  const body = {
    project: { id: "p1", name: "demo" },
    items: [{ id: "a" }, { id: "b" }],
    count: 2,
    nested: { list: [{ tags: ["x", "y"] }] },
  };

  it("reads dotted object paths", () => {
    expect(extractPath(body, "project.id")).toBe("p1");
  });

  it("reads array indices with bracket and dot notation", () => {
    expect(extractPath(body, "items[0].id")).toBe("a");
    expect(extractPath(body, "items.1.id")).toBe("b");
  });

  it("reads deeply nested array values", () => {
    expect(extractPath(body, "nested.list[0].tags[1]")).toBe("y");
  });

  it("returns undefined for missing keys or out-of-range indices", () => {
    expect(extractPath(body, "project.missing")).toBeUndefined();
    expect(extractPath(body, "items[9].id")).toBeUndefined();
    expect(extractPath(body, "count.nope")).toBeUndefined();
  });

  it("returns undefined when descending into null", () => {
    expect(extractPath({ a: null }, "a.b")).toBeUndefined();
  });
});

describe("stringifyExtracted", () => {
  it("passes primitives through", () => {
    expect(stringifyExtracted("abc")).toBe("abc");
    expect(stringifyExtracted(42)).toBe("42");
    expect(stringifyExtracted(true)).toBe("true");
  });

  it("serializes objects and arrays as JSON", () => {
    expect(stringifyExtracted({ a: 1 })).toBe('{"a":1}');
    expect(stringifyExtracted([1, 2])).toBe("[1,2]");
  });

  it("renders null and undefined as an empty string", () => {
    expect(stringifyExtracted(null)).toBe("");
    expect(stringifyExtracted(undefined)).toBe("");
  });
});

import { describe, expect, it } from "vitest";
import {
  filterOperations,
  parseMethod,
  resolveOperationsOrThrow,
  scopeOperations,
} from "./operation-filter.js";
import type { SpecOperation } from "./spec-loader.js";

function op(overrides: Partial<SpecOperation>): SpecOperation {
  return {
    method: "get",
    path: "/",
    tags: [],
    deprecated: false,
    secured: false,
    authParameters: [],
    parameters: [],
    responses: {},
    ...overrides,
  };
}

const operations: SpecOperation[] = [
  op({ method: "get", path: "/pets", tags: ["pets"], summary: "list pets" }),
  op({ method: "post", path: "/pets", tags: ["pets"], summary: "create pet" }),
  op({ method: "get", path: "/admin/stats", tags: ["admin"], summary: "stats" }),
];

describe("filterOperations", () => {
  it("filters by tag", () => {
    expect(filterOperations(operations, { tag: "admin" })).toHaveLength(1);
  });

  it("filters by method", () => {
    expect(filterOperations(operations, { method: "post" })).toHaveLength(1);
  });

  it("filters by path glob", () => {
    expect(filterOperations(operations, { path: "/admin/**" })).toHaveLength(1);
  });

  it("filters by free-text search", () => {
    expect(filterOperations(operations, { search: "create" })).toHaveLength(1);
  });

  it("combines filters", () => {
    expect(filterOperations(operations, { tag: "pets", method: "get" })).toHaveLength(1);
  });
});

describe("parseMethod", () => {
  it("accepts known methods case-insensitively", () => {
    expect(parseMethod("POST")).toBe("post");
  });

  it("rejects unknown methods", () => {
    expect(() => parseMethod("connectx")).toThrow(/--method must be one of/);
  });
});

describe("scopeOperations", () => {
  it("applies method and OpenAPI path scope", () => {
    expect(
      scopeOperations(operations, { allowedMethods: ["GET"], allowedPaths: ["/pets"] }).map(
        (operation) => `${operation.method} ${operation.path}`,
      ),
    ).toEqual(["get /pets"]);
  });
});

describe("resolveOperationsOrThrow", () => {
  it("throws VALIDATION_ERROR when explicit filters match nothing", () => {
    expect(() => resolveOperationsOrThrow(operations, { tag: "ghost" })).toThrow();
  });

  it("does not throw on empty result without filters", () => {
    expect(resolveOperationsOrThrow([], {})).toEqual([]);
  });
});
